package com.splitmate.service;
import com.splitmate.api.ApiDtos.*;import com.splitmate.domain.*;import com.splitmate.repo.*;import org.junit.jupiter.api.*;import org.mockito.*;import org.springframework.security.crypto.password.PasswordEncoder;import java.math.*;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class SplitMateServiceTest {
 @Mock UserRepository users;@Mock HouseholdRepository households;@Mock MembershipRepository memberships;@Mock ExpenseRepository expenses;@Mock ExpenseShareRepository shares;@Mock SettlementRepository settlements;@Mock PasswordEncoder encoder;SplitMateService service;
 @BeforeEach void setup(){MockitoAnnotations.openMocks(this);service=new SplitMateService(users,households,memberships,expenses,shares,settlements,encoder);}
 @Test void equalSplitDistributesRemainderWithoutLosingCents(){List<ShareInput> result=service.equalShares(new BigDecimal("10.00"),List.of(1L,2L,3L));assertEquals(new BigDecimal("3.34"),result.get(0).amount());assertEquals(new BigDecimal("3.33"),result.get(1).amount());assertEquals(new BigDecimal("3.33"),result.get(2).amount());assertEquals(new BigDecimal("10.00"),result.stream().map(ShareInput::amount).reduce(BigDecimal.ZERO,BigDecimal::add));}
 @Test void minimumTransfersMatchNetDebts(){when(users.findById(1L)).thenReturn(Optional.of(new User("A","a@example.com","x")));when(users.findById(2L)).thenReturn(Optional.of(new User("B","b@example.com","x")));when(users.findById(3L)).thenReturn(Optional.of(new User("C","c@example.com","x")));var result=service.transfers(Map.of(1L,new BigDecimal("10.00"),2L,new BigDecimal("-6.00"),3L,new BigDecimal("-4.00")));assertEquals(2,result.size());assertEquals(new BigDecimal("6.00"),result.get(0).amount());assertEquals(new BigDecimal("4.00"),result.get(1).amount());}
}
